from __future__ import annotations
import itertools, copy
from dataclasses import dataclass, field
import numpy as np, pandas as pd, torch, torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset
from concurrent.futures import ThreadPoolExecutor, as_completed
"""Triple-barrier labeling (AFML ch.3).

Mỗi bar i là 1 event: entry = close[i].
  barrier trên  = close[i] * exp(+width[i])
  barrier dưới  = close[i] * exp(-width[i])
  vertical      = bar i + horizon
width mặc định = rolling_std(logret, vol_window) * sqrt(horizon) * width_mult
(vol theo bar nhân sqrt(horizon) ≈ vol của cả quãng event — barrier cân với horizon).

Label: +1 chạm trên trước, -1 chạm dưới trước, 0 hết giờ.
Chạm xét bằng high/low các bar i+1..i+horizon. Nếu 1 bar chạm CẢ 2 barrier
thì không biết cái nào trước (không có dữ liệu trong bar) -> label 0 + cờ
`ambiguous` để downstream tự quyết lọc hay giữ.

Event thiếu đường chạy (gần cuối data / width NaN) -> `complete=False`,
label giữ 0 làm placeholder — KHÔNG được dùng để train.
"""




@dataclass
class LabelConfig:
    horizon: int = 50        # vertical barrier, tính bằng số bars
    width_mult: float = 1.0  # hệ số nhân width
    vol_window: int = 50     # cửa sổ vol khi width không truyền vào


def triple_barrier(bars: pd.DataFrame, cfg: LabelConfig,
                   width: np.ndarray | None = None) -> pd.DataFrame:
    """bars cần close/high/low/t_close. Trả về DataFrame cùng index:
    t_close, label(int8), t_end_idx, t_end, ret, ambiguous, complete."""
    c = bars["close"].to_numpy(dtype=np.float64)
    h = bars["high"].to_numpy(dtype=np.float64)
    l = bars["low"].to_numpy(dtype=np.float64)
    n = len(c)
    idx = np.arange(n)

    if width is None:
        logret = np.diff(np.log(c), prepend=np.nan)
        vol = pd.Series(logret).rolling(cfg.vol_window).std().to_numpy()
        width = vol * np.sqrt(cfg.horizon) * cfg.width_mult
    else:
        width = np.asarray(width, dtype=np.float64) * cfg.width_mult

    up = c * np.exp(width)
    dn = c * np.exp(-width)

    complete = np.isfinite(width) & (idx + cfg.horizon <= n - 1)
    label = np.zeros(n, dtype=np.int8)
    ambiguous = np.zeros(n, dtype=bool)
    resolved = np.zeros(n, dtype=bool)
    t_end_idx = np.minimum(idx + cfg.horizon, n - 1)

    # quét theo offset: mỗi vòng xử lý "bar thứ off sau entry" cho MỌI event
    # cùng lúc (O(horizon) vòng numpy thay vì O(n*horizon) python)
    for off in range(1, cfg.horizon + 1):
        j = np.minimum(idx + off, n - 1)
        active = complete & ~resolved & (idx + off <= n - 1)
        up_hit = active & (h[j] >= up)
        dn_hit = active & (l[j] <= dn)
        both = up_hit & dn_hit
        label[up_hit & ~both] = 1
        label[dn_hit & ~both] = -1
        ambiguous[both] = True  # label giữ 0
        hit = up_hit | dn_hit
        t_end_idx[hit] = idx[hit] + off
        resolved |= hit

    ret = np.log(c[t_end_idx] / c)
    ret[~complete] = np.nan

    return pd.DataFrame({
        "t_close": bars["t_close"].to_numpy(),
        "label": label,
        "t_end_idx": t_end_idx,
        "t_end": bars["t_close"].to_numpy()[t_end_idx],
        "ret": ret,
        "ambiguous": ambiguous,
        "complete": complete,
    }, index=bars.index)
"""Join features + labels, split theo thời gian có purge, chuẩn hóa.

- Split: train/val/test theo THỜI GIAN (không shuffle — time series).
- Purge: event nào có t_end vượt qua ranh giới split thì bỏ — label của nó
  nhìn thấy giá thuộc split sau (leakage).
- Chuẩn hóa: z-score với mean/std fit CHỈ trên train, clip ±clip.
- Label -1/0/+1 -> class 0/1/2 (CrossEntropyLoss).
"""




@dataclass
class DatasetConfig:
    train_frac: float = 0.7
    val_frac: float = 0.15
    purge: int = 50            # số bar đệm tại ranh giới (>= horizon của label)
    clip: float = 5.0
    feature_cols: list[str] = field(default_factory=list)  # rỗng = tự suy ra


def build_dataset(features: pd.DataFrame, labels: pd.DataFrame,
                  cfg: DatasetConfig) -> dict:
    """Trả về dict: X_/y_/t_ cho train/val/test (numpy), norm_mean/std, feature_cols."""
    lab_cols = ["t_close", "label", "t_end", "ret"]
    df = features.merge(
        labels.loc[labels["complete"] & ~labels["ambiguous"], lab_cols],
        on="t_close", how="inner").sort_values("t_close", ignore_index=True)

    feat_cols = cfg.feature_cols or [
        c for c in features.columns if c not in ("t_close", "close")]

    n = len(df)
    a = int(n * cfg.train_frac)
    b = int(n * (cfg.train_frac + cfg.val_frac))
    t = df["t_close"].to_numpy()
    t_end = df["t_end"].to_numpy()

    idx = np.arange(n)
    parts = {
        "train": (idx < a) & (t_end < t[a]) if a < n else idx < a,
        "val": (idx >= a) & (idx < b) & (t_end < t[b]) if b < n else (idx >= a) & (idx < b),
        "test": idx >= b,
    }

    tr = df.loc[parts["train"], feat_cols].to_numpy(dtype=np.float64)
    mean, std = tr.mean(axis=0), tr.std(axis=0)
    std = np.where(std < 1e-12, 1.0, std)

    out = {"feature_cols": feat_cols, "norm_mean": mean, "norm_std": std}
    for name, mask in parts.items():
        X = df.loc[mask, feat_cols].to_numpy(dtype=np.float64)
        X = np.clip((X - mean) / std, -cfg.clip, cfg.clip)
        out[f"X_{name}"] = X.astype(np.float32)
        out[f"y_{name}"] = (df.loc[mask, "label"].to_numpy() + 1).astype(np.int64)
        out[f"t_{name}"] = df.loc[mask, "t_close"].to_numpy()
        out[f"ret_{name}"] = df.loc[mask, "ret"].to_numpy(dtype=np.float64)
    return out
"""MLP baseline dự đoán hướng 3 class (xuống/đi ngang/lên).

Giữ đơn giản có chủ đích — baseline phải chạy được trước khi nghĩ tới
kiến trúc phức tạp (sequence model để v2).
"""



class DirectionNet(nn.Module):
    def __init__(self, n_features: int, hidden: tuple[int, ...] = (128, 64),
                 dropout: float = 0.2, n_classes: int = 3):
        super().__init__()
        layers: list[nn.Module] = []
        prev = n_features
        for h in hidden:
            layers += [nn.Linear(prev, h), nn.LayerNorm(h), nn.ReLU(), nn.Dropout(dropout)]
            prev = h
        layers.append(nn.Linear(prev, n_classes))
        self.net = nn.Sequential(*layers)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)
"""Train loop cho DirectionNet: Adam + cross-entropy + early stopping theo val loss.

train_model() là hàm thuần (numpy vào, dict ra) để test được;
CLI ở cuối file gọi nó với features/labels parquet thật.
"""





@dataclass
class TrainConfig:
    epochs: int = 100
    batch_size: int = 1024
    lr: float = 1e-3
    weight_decay: float = 1e-4
    patience: int = 10          # early stopping theo val loss
    hidden: tuple[int, ...] = (128, 64)
    dropout: float = 0.2
    seed: int = 42
    device: str = ""            # "" = tự chọn cuda nếu có


def train_model(X_train: np.ndarray, y_train: np.ndarray,
                X_val: np.ndarray, y_val: np.ndarray,
                cfg: TrainConfig, log_every: int = 0) -> dict:
    torch.manual_seed(cfg.seed)
    dev = cfg.device or ("cuda" if torch.cuda.is_available() else "cpu")

    net = DirectionNet(X_train.shape[1], hidden=cfg.hidden, dropout=cfg.dropout).to(dev)
    opt = torch.optim.Adam(net.parameters(), lr=cfg.lr, weight_decay=cfg.weight_decay)
    loss_fn = nn.CrossEntropyLoss()

    train_dl = DataLoader(
        TensorDataset(torch.from_numpy(X_train), torch.from_numpy(y_train)),
        batch_size=cfg.batch_size, shuffle=True)
    Xv = torch.from_numpy(X_val).to(dev)
    yv = torch.from_numpy(y_val).to(dev)

    best = {"val_loss": float("inf"), "val_acc": 0.0, "state_dict": None, "best_epoch": 0}
    bad = 0
    epoch = 0
    for epoch in range(1, cfg.epochs + 1):
        net.train()
        for xb, yb in train_dl:
            xb, yb = xb.to(dev), yb.to(dev)
            opt.zero_grad()
            loss_fn(net(xb), yb).backward()
            opt.step()

        net.eval()
        with torch.no_grad():
            logits = net(Xv)
            val_loss = float(loss_fn(logits, yv))
            val_acc = float((logits.argmax(1) == yv).float().mean())
        if log_every and epoch % log_every == 0:
            print(f"  epoch {epoch:3d}: val_loss={val_loss:.4f} val_acc={val_acc:.4f}")

        if val_loss < best["val_loss"]:
            best.update(val_loss=val_loss, val_acc=val_acc, best_epoch=epoch,
                        state_dict=copy.deepcopy(
                            {k: v.cpu() for k, v in net.state_dict().items()}))
            bad = 0
        else:
            bad += 1
            if bad >= cfg.patience:
                break

    best["last_epoch"] = epoch
    return best
"""Hyperparameter sweep: build lưới combo, chạy song song trên nhiều GPU.

Model quá nhỏ để 1 trial cần cả GPU (13k-100k tham số) -> tận dụng nhiều
GPU bằng cách chạy NHIỀU TRIAL cùng lúc, mỗi trial ghim vào 1 device,
thay vì chia 1 trial ra nhiều GPU (DataParallel vô nghĩa ở quy mô này).

ThreadPoolExecutor (không phải multiprocessing) vì:
- CUDA context không fork được sau khi đã init -> multiprocessing cần
  spawn + set CUDA_VISIBLE_DEVICES trước khi import torch, phức tạp.
- PyTorch hỗ trợ nhiều CUDA device trong cùng 1 process; mỗi trial chỉ
  đụng đúng device được gán, không share state với trial khác.
- Phần lâu nhất (forward/backward) release GIL trong lúc chạy CUDA kernel
  nên threads vẫn chạy được thật sự song song trên các GPU khác nhau.
"""





@dataclass(frozen=True)
class Trial:
    horizon: int
    width_mult: float
    hidden: tuple[int, ...]
    dropout: float
    lr: float
    weight_decay: float


def build_grid(horizons, width_mults, hiddens, dropouts, lrs, weight_decays) -> list[Trial]:
    return [Trial(*combo) for combo in itertools.product(
        horizons, width_mults, hiddens, dropouts, lrs, weight_decays)]


def _run_one(trial: Trial, ds: dict, device: str, train_overrides: dict) -> dict:
    cfg = TrainConfig(hidden=trial.hidden, dropout=trial.dropout, lr=trial.lr,
                      weight_decay=trial.weight_decay, device=device, **train_overrides)
    result = train_model(ds["X_train"], ds["y_train"], ds["X_val"], ds["y_val"], cfg)

    net = DirectionNet(ds["X_train"].shape[1], hidden=trial.hidden, dropout=trial.dropout).to(device)
    net.load_state_dict(result["state_dict"])
    net.eval()
    with torch.no_grad():
        logits = net(torch.from_numpy(ds["X_test"]).to(device))
        prob = torch.softmax(logits, 1).cpu().numpy()
    pred = prob.argmax(1)
    conf = prob.max(1)
    y_test = ds["y_test"]
    ret_test = ds["ret_test"]
    test_acc = float((pred == y_test).mean())

    row = {
        "horizon": trial.horizon, "width_mult": trial.width_mult,
        "hidden": str(trial.hidden), "dropout": trial.dropout,
        "lr": trial.lr, "weight_decay": trial.weight_decay,
        "best_epoch": result["best_epoch"], "val_loss": result["val_loss"],
        "val_acc": result["val_acc"], "test_acc": test_acc,
        "n_train": len(ds["y_train"]),
    }
    for th in (0.0, 0.40, 0.45, 0.50):
        m_up = (pred == 2) & (conf >= th)
        m_dn = (pred == 0) & (conf >= th)
        n = int(m_up.sum() + m_dn.sum())
        edge = float(np.concatenate([ret_test[m_up], -ret_test[m_dn]]).mean()) if n else float("nan")
        row[f"edge_conf{th:.2f}"] = edge
        row[f"n_conf{th:.2f}"] = n
    return row


def run_sweep(datasets: dict[tuple[int, float], dict], grid: list[Trial],
             devices: list[str], train_overrides: dict | None = None) -> pd.DataFrame:
    """datasets keyed bởi (horizon, width_mult) -> dict từ build_dataset.
    Trial nào không tìm thấy dataset khớp sẽ raise KeyError ngay (fail fast,
    không âm thầm bỏ qua trial)."""
    train_overrides = train_overrides or {}
    for t in grid:
        if (t.horizon, t.width_mult) not in datasets:
            raise KeyError(f"thiếu dataset cho (horizon={t.horizon}, width_mult={t.width_mult})")

    rows = [None] * len(grid)
    with ThreadPoolExecutor(max_workers=len(devices)) as ex:
        futs = {
            ex.submit(_run_one, t, datasets[(t.horizon, t.width_mult)],
                     devices[i % len(devices)], train_overrides): i
            for i, t in enumerate(grid)
        }
        for fut in as_completed(futs):
            rows[futs[fut]] = fut.result()
    return pd.DataFrame(rows)
